/* GENERATED by gen_hcon_augmented.py -- models are generated.
   SAT_PARTY_HEALTH_PROFILE
   *** UNRATIFIED. This payload is a BUILD-SIDE PROPOSAL from the map's
   augmentation blocks and has NOT been ratified by the modeller. Attributes here
   are not declared on this satellite in data_7.js. Do not treat it as part of the
   ratified vault. ***
   anchor      : HUB_PARTY   (kind: hub, origin: map.anchor)
   track       : unratified
   history     : SCD2
   feeders     : 2 emitted of 2 (one per source view AND run)
   runs        : 2 -- opus_health_legacy_v4, opus_health_v2
   payload     : 5 attribute(s), NULL-PADDED TO THE SATELLITE
   grain       : ONE ROW PER HUB_PARTY_HK
   hashdiff    : SAT_PARTY_HEALTH_PROFILE_HASHDIFF (builder decision BD1), GUARDED against an all-null input (s5.5):
                 without the guard every all-null row hashes to ONE value and the
                 satellite collapses to one row, which looks like change detection.
   BESPOKE LAYER dual_feed_satellite_loader (s6.5): BOTH runs write this satellite.
   The standard satellite layer unions feeders that are disjoint by construction,
   which is the assumption two independent writers break.
*/

with feeders as (
    select
        md5(upper('HUB_PARTY|' || (HUB_PARTY_BK__MEMBER_NO))) as HUB_PARTY_HK
        , FAMILY_HIST_DETAILS as FAMILY_MEDICAL_HISTORY_DESCRIPTION
        , cast(null as varchar) as OBSTETRIC_GRAVIDA_COUNT
        , cast(null as varchar) as OBSTETRIC_PARA_COUNT
        , cast(null as varchar) as OBSTETRIC_LIVE_BIRTH_COUNT
        , cast(null as varchar) as OBSTETRIC_ABORTION_COUNT
        , 'BJAZ_HAT_ID_MEM_DETLS' as RECORD_SOURCE
        , 'opus_health_legacy_v4' as SOURCE_RUN
        , current_timestamp() as LOAD_DATETIME
    from {{ ref('stage_hat_id_mem_detls') }}
    where (nullif(trim(MEMBER_NO),'')) is not null
    union all
    select
        md5(upper('HUB_PARTY|' || (HUB_PARTY_BK__HOS_ID))) as HUB_PARTY_HK
        , cast(null as varchar) as FAMILY_MEDICAL_HISTORY_DESCRIPTION
        , MATERNITY_G as OBSTETRIC_GRAVIDA_COUNT
        , MATERNITY_P as OBSTETRIC_PARA_COUNT
        , MATERNITY_L as OBSTETRIC_LIVE_BIRTH_COUNT
        , MATERNITY_A as OBSTETRIC_ABORTION_COUNT
        , 'BJAZ_HM_PREAUTH_REQUEST' as RECORD_SOURCE
        , 'opus_health_v2' as SOURCE_RUN
        , current_timestamp() as LOAD_DATETIME
    from {{ ref('stage_hm_preauth_request') }}
    where (nullif('HOSPID:' || nullif(trim(HOS_ID),''), 'HOSPID:')) is not null
),

resolved as (
    select
        HUB_PARTY_HK,
        max(case when SOURCE_RUN = 'opus_health_legacy_v4' then FAMILY_MEDICAL_HISTORY_DESCRIPTION end) as FAMILY_MEDICAL_HISTORY_DESCRIPTION,
        max(case when SOURCE_RUN = 'opus_health_v2' then OBSTETRIC_GRAVIDA_COUNT end) as OBSTETRIC_GRAVIDA_COUNT,
        max(case when SOURCE_RUN = 'opus_health_v2' then OBSTETRIC_PARA_COUNT end) as OBSTETRIC_PARA_COUNT,
        max(case when SOURCE_RUN = 'opus_health_v2' then OBSTETRIC_LIVE_BIRTH_COUNT end) as OBSTETRIC_LIVE_BIRTH_COUNT,
        max(case when SOURCE_RUN = 'opus_health_v2' then OBSTETRIC_ABORTION_COUNT end) as OBSTETRIC_ABORTION_COUNT,
        min(RECORD_SOURCE) as RECORD_SOURCE,
        min(SOURCE_RUN) as SOURCE_RUN,
        min(LOAD_DATETIME) as LOAD_DATETIME
    from feeders
    group by HUB_PARTY_HK
),

hashed as (
    select
        *,
        case when FAMILY_MEDICAL_HISTORY_DESCRIPTION is not null or OBSTETRIC_GRAVIDA_COUNT is not null or OBSTETRIC_PARA_COUNT is not null or OBSTETRIC_LIVE_BIRTH_COUNT is not null or OBSTETRIC_ABORTION_COUNT is not null
                     then md5(upper(coalesce(cast(FAMILY_MEDICAL_HISTORY_DESCRIPTION as varchar), '') || '|' || coalesce(cast(OBSTETRIC_GRAVIDA_COUNT as varchar), '') || '|' || coalesce(cast(OBSTETRIC_PARA_COUNT as varchar), '') || '|' || coalesce(cast(OBSTETRIC_LIVE_BIRTH_COUNT as varchar), '') || '|' || coalesce(cast(OBSTETRIC_ABORTION_COUNT as varchar), '')))
                end as SAT_PARTY_HEALTH_PROFILE_HASHDIFF
    from resolved
)

select * from hashed
where HUB_PARTY_HK is not null
  and SAT_PARTY_HEALTH_PROFILE_HASHDIFF is not null
